window.GRIM_PARTS["details-86"]=[{"id":"g0079","name":"发亮的力量点","category":"guides","subcategory":"游戏内生存提示","summary":"带头盖标志的地点偶尔会有发亮的力量点。通过与其互动，你获得烈士的祝福，以此获得不同的优势。","image":"assets/images/a804f7d77d4e1.webp","stats":[{"label":"收录提示","value":1}],"sections":[{"title":"提示 1","text":"带头盖标志的地点偶尔会有发亮的力量点。通过与其互动，你获得烈士的祝福，以此获得不同的优势。"}],"related":[]},{"id":"g0080","name":"红天使守护","category":"guides","subcategory":"游戏内生存提示","summary":"红天使守护将使你的生存更加舒适，并为游戏增加一些便捷的功能。","image":"assets/images/a4936e0993f0d.webp","stats":[{"label":"收录提示","value":1}],"sections":[{"title":"提示 1","text":"红天使守护将使你的生存更加舒适，并为游戏增加一些便捷的功能。"}],"related":[]},{"id":"g0081","name":"英雄地下城模式","category":"guides","subcategory":"游戏内生存提示","summary":"不觉得这个游戏很有挑战性吗? 尝试在英雄难度中挑战地下城吧!","image":"assets/images/ae163ee754339.webp","stats":[{"label":"收录提示","value":3}],"sections":[{"title":"提示 1","text":"不觉得这个游戏很有挑战性吗? 尝试在英雄难度中挑战地下城吧!"},{"title":"提示 2","text":"在英雄模式下，地下城将会依照多样的修改器在每一次玩的时候做改变。"},{"title":"提示 3","text":"在英雄模式下，地下城的敌人们会死而复活。"}],"related":[]},{"id":"g0082","name":"暗祭","category":"guides","subcategory":"游戏内生存提示","summary":"有时流亡者会发现暗祭的祭坛。将够宝贵的物品放在祭坛上，也许天上的力量会给予报酬。","image":"assets/images/a559d6283aa75.webp","stats":[{"label":"收录提示","value":1}],"sections":[{"title":"提示 1","text":"有时流亡者会发现暗祭的祭坛。将够宝贵的物品放在祭坛上，也许天上的力量会给予报酬。"}],"related":[]},{"id":"g0083","name":"罗格沃尔的影子","category":"guides","subcategory":"游戏内生存提示","summary":"罗格沃尔曾经是哀悼死神骑士团的主人。现在，他变成了一个巨大的异界怪物，困在死者与活人的国度之间。","image":"assets/images/a0bec120006bc.webp","stats":[{"label":"收录提示","value":1}],"sections":[{"title":"提示 1","text":"罗格沃尔曾经是哀悼死神骑士团的主人。现在，他变成了一个巨大的异界怪物，困在死者与活人的国度之间。"}],"related":[]},{"id":"g0084","name":"雷电","category":"guides","subcategory":"游戏内生存提示","summary":"暴风来临时，有时会有闪电击中地面。如果你迅速逃离了将击中的区域，就能避免被击中。","image":"","stats":[{"label":"收录提示","value":1}],"sections":[{"title":"提示 1","text":"暴风来临时，有时会有闪电击中地面。如果你迅速逃离了将击中的区域，就能避免被击中。"}],"related":[]},{"id":"g0085","name":"邻居","category":"guides","subcategory":"游戏内生存提示","summary":"当地流亡者的家会在省地图上不时刷新。千万别放过在刷新前洗劫他们箱子的机会！","image":"","stats":[{"label":"收录提示","value":2}],"sections":[{"title":"提示 1","text":"当地流亡者的家会在省地图上不时刷新。千万别放过在刷新前洗劫他们箱子的机会！"},{"title":"提示 2","text":"邻居们总是随身带着他们最值钱宝箱的钥匙。前往骷髅地点打败他们获取钥匙，再带上炸药去拜访他们的家吧。"}],"related":[]},{"id":"g0086","name":"教派","category":"guides","subcategory":"游戏内生存提示","summary":"通过完成任务，你可以选择与瘟疫之地的三个教派，瘟疫之神，无名之神，赫拉特教会结盟。深思熟虑再做选择，每个教派都会给你与众不同的能力。","image":"","stats":[{"label":"收录提示","value":2}],"sections":[{"title":"提示 1","text":"通过完成任务，你可以选择与瘟疫之地的三个教派，瘟疫之神，无名之神，赫拉特教会结盟。深思熟虑再做选择，每个教派都会给你与众不同的能力。"},{"title":"提示 2","text":"你可以换教派，但是记住了：你一次只能拥有一个教派的特殊能力。同时，你在某一教派获得的虔诚点将无法转换到其他教派。"}],"related":[]},{"id":"g0087","name":"地下神祠","category":"guides","subcategory":"游戏内生存提示","summary":"可以找到酷吏地下城钥匙的特殊地点。但其中的秘密不仅止于此。","image":"assets/images/ac353d7510266.webp","stats":[{"label":"收录提示","value":2}],"sections":[{"title":"提示 1","text":"可以找到酷吏地下城钥匙的特殊地点。但其中的秘密不仅止于此。"},{"title":"提示 2","text":"你需要地图才能找到地下神祠。"}],"related":[]},{"id":"g0088","name":"酷吏地下城","category":"guides","subcategory":"游戏内生存提示","summary":"酷吏是瘟疫之神最危险的仆从之一。他们带来的挑战比被弃者大得多。","image":"assets/images/a5ec76781371e.webp","stats":[{"label":"收录提示","value":4}],"sections":[{"title":"提示 1","text":"酷吏是瘟疫之神最危险的仆从之一。他们带来的挑战比被弃者大得多。"},{"title":"提示 2","text":"进入地下城时请带上炸弹。它们会帮助你到达隐藏的宝藏。"},{"title":"提示 3","text":"地下城中充满了狡猾的陷阱，会让没有经验的流亡者非常痛苦。"},{"title":"提示 4","text":"要想到达最后的宝箱，你不仅要生存下来，还要解决地下城的谜题。"}],"related":[]},{"id":"g0089","name":"魔法宝箱","category":"guides","subcategory":"游戏内生存提示","summary":"把补给放在里面，以便在地下城突袭期间取用。","image":"assets/images/a8a1345ca4a8f.webp","stats":[{"label":"收录提示","value":1}],"sections":[{"title":"提示 1","text":"把补给放在里面，以便在地下城突袭期间取用。"}],"related":[]},{"id":"g0090","name":"共同奋战","category":"guides","subcategory":"游戏内生存提示","summary":"你的好友可以帮助你收集钥匙，让你获得有价值的奖励。不要忘了礼尚往来！","image":"assets/images/adf96af2778df.webp","stats":[{"label":"收录提示","value":1}],"sections":[{"title":"提示 1","text":"你的好友可以帮助你收集钥匙，让你获得有价值的奖励。不要忘了礼尚往来！"}],"related":[]},{"id":"g0091","name":"教徒地窖","category":"guides","subcategory":"游戏内生存提示","summary":"寻宝时要注意，有时你会发现一条通往隐藏地下城的路。","image":"assets/images/a3aa0f52103c9.webp","stats":[{"label":"收录提示","value":1}],"sections":[{"title":"提示 1","text":"寻宝时要注意，有时你会发现一条通往隐藏地下城的路。"}],"related":[]},{"id":"g0092","name":"战斗彩绘","category":"guides","subcategory":"游戏内生存提示","summary":"解锁新的角色定制选项，突出你的个性。","image":"assets/images/a6ffd79a1eab7.webp","stats":[{"label":"收录提示","value":1}],"sections":[{"title":"提示 1","text":"解锁新的角色定制选项，突出你的个性。"}],"related":[]},{"id":"g0093","name":"重生","category":"guides","subcategory":"游戏内生存提示","summary":"你可以与狡猾吝啬鬼打牌来获得史诗恐狼，它的嚎叫可以使死去的主人重生。","image":"assets/images/a43ac20d45eb9.webp","stats":[{"label":"收录提示","value":1}],"sections":[{"title":"提示 1","text":"你可以与狡猾吝啬鬼打牌来获得史诗恐狼，它的嚎叫可以使死去的主人重生。"}],"related":[]},{"id":"g0094","name":"卡牌游戏","category":"guides","subcategory":"游戏内生存提示","summary":"在卡牌游戏中升级，每回合可换更多的牌。","image":"assets/images/a771a0c8cff62.webp","stats":[{"label":"收录提示","value":2}],"sections":[{"title":"提示 1","text":"在卡牌游戏中升级，每回合可换更多的牌。"},{"title":"提示 2","text":"在卡牌游戏中升级。每升5级就能获得额外的奖励。"}],"related":[]},{"id":"g0095","name":"史诗级恐狼","category":"guides","subcategory":"游戏内生存提示","summary":"这种极其强大的恐狼只会获得独特、传奇和史诗技能。要获得这样的狼，请玩牌。","image":"assets/images/ae47e6f55e986.webp","stats":[{"label":"收录提示","value":1}],"sections":[{"title":"提示 1","text":"这种极其强大的恐狼只会获得独特、传奇和史诗技能。要获得这样的狼，请玩牌。"}],"related":[]},{"id":"g0096","name":"元素","category":"guides","subcategory":"游戏内生存提示","summary":"护甲只保护你免受物理伤害。元素伤害可以通过具有正确元素防御的护甲来降低。","image":"assets/images/a9a8ed2747432.webp","stats":[{"label":"收录提示","value":2}],"sections":[{"title":"提示 1","text":"护甲只保护你免受物理伤害。元素伤害可以通过具有正确元素防御的护甲来降低。"},{"title":"提示 2","text":"一些敌人和陷阱不仅会造成物理伤害，还会造成元素伤害。"}],"related":[]},{"id":"g0097","name":"酷刑架","category":"guides","subcategory":"游戏内生存提示","summary":"审问酷吏侦察员，以到达酷吏地下城第二层入口，发现达到财宝的最短路径。","image":"assets/images/a3c0b2a754993.webp","stats":[{"label":"收录提示","value":1}],"sections":[{"title":"提示 1","text":"审问酷吏侦察员，以到达酷吏地下城第二层入口，发现达到财宝的最短路径。"}],"related":[]},{"id":"g0098","name":"对各类伤害的脆弱性","category":"guides","subcategory":"游戏内生存提示","summary":"有些敌人对物理或元素伤害有很好的防护能力。为了打败他们，请选择能造成必要类型伤害的武器。","image":"assets/images/a9a8ed2747432.webp","stats":[{"label":"收录提示","value":1}],"sections":[{"title":"提示 1","text":"有些敌人对物理或元素伤害有很好的防护能力。为了打败他们，请选择能造成必要类型伤害的武器。"}],"related":[]},{"id":"g0099","name":"高炉","category":"guides","subcategory":"游戏内生存提示","summary":"让你熔炼用于打造最佳护甲和武器的钢材。","image":"assets/images/a54339209605e.webp","stats":[{"label":"收录提示","value":1}],"sections":[{"title":"提示 1","text":"让你熔炼用于打造最佳护甲和武器的钢材。"}],"related":[]},{"id":"g0100","name":"酷吏侦察员","category":"guides","subcategory":"游戏内生存提示","summary":"在北方和地下城附近经常会遇到侦察员。要抓住酷吏侦察员，请对其使用3级控制卷轴。","image":"assets/images/a859a7456dce3.webp","stats":[{"label":"收录提示","value":1}],"sections":[{"title":"提示 1","text":"在北方和地下城附近经常会遇到侦察员。要抓住酷吏侦察员，请对其使用3级控制卷轴。"}],"related":[]},{"id":"g0101","name":"被弃隐士","category":"guides","subcategory":"游戏内生存提示","summary":"在三骷髅地点经常会遇到隐士。要抓住被弃隐士，请对其使用控制卷轴。","image":"assets/images/adc07a764a77e.webp","stats":[{"label":"收录提示","value":1}],"sections":[{"title":"提示 1","text":"在三骷髅地点经常会遇到隐士。要抓住被弃隐士，请对其使用控制卷轴。"}],"related":[]},{"id":"g0102","name":"厨师","category":"guides","subcategory":"游戏内生存提示","summary":"在厨师的帮助下，你可以在红天使营地制作各种菜肴。","image":"assets/images/a3bbce22b2405.webp","stats":[{"label":"收录提示","value":2}],"sections":[{"title":"提示 1","text":"在厨师的帮助下，你可以在红天使营地制作各种菜肴。"},{"title":"提示 2","text":"厨师可以做很多不同的菜肴。你可以进行实验或寻找配方。"}],"related":[]},{"id":"g0103","name":"侦察员","category":"guides","subcategory":"游戏内生存提示","summary":"在红天使营地与侦察员交谈。他可以帮你用地图碎片创建完整的地图。","image":"assets/images/a351a445a81a7.webp","stats":[{"label":"收录提示","value":2}],"sections":[{"title":"提示 1","text":"在红天使营地与侦察员交谈。他可以帮你用地图碎片创建完整的地图。"},{"title":"提示 2","text":"在红天使营地的侦察员可以用地图交换食物或其他有价值的物品。常来看看。"}],"related":[]},{"id":"g0104","name":"猫咪等级","category":"guides","subcategory":"游戏内生存提示","summary":"与恐狼不同，猫咪不与敌人战斗。它们通过在实用效果上消耗能量以获得经验值。","image":"assets/images/abe008fbbdd51.webp","stats":[{"label":"收录提示","value":1}],"sections":[{"title":"提示 1","text":"与恐狼不同，猫咪不与敌人战斗。它们通过在实用效果上消耗能量以获得经验值。"}],"related":[]},{"id":"g0105","name":"地点地图","category":"guides","subcategory":"游戏内生存提示","summary":"你可以在任何时间使用地图并触发游戏活动。","image":"assets/images/a559d6283aa75.webp","stats":[{"label":"收录提示","value":2}],"sections":[{"title":"提示 1","text":"你可以在任何时间使用地图并触发游戏活动。"},{"title":"提示 2","text":"你可以在游戏地点获得活动地图作为战利品。"}],"related":[]},{"id":"g0106","name":"死者之书","category":"guides","subcategory":"游戏内生存提示","summary":"你可以在暗祭祭坛上献上命运之书来获得死者之书。","image":"assets/images/aa0ece32786b2.webp","stats":[{"label":"收录提示","value":1}],"sections":[{"title":"提示 1","text":"你可以在暗祭祭坛上献上命运之书来获得死者之书。"}],"related":[]}];
